  "《貓貓啟示錄：緋月之森》原創黑暗童話動作冒險。":["《猫猫启示录：绯月之森》原创黑暗童话动作冒险。","Meow Revelation: Crimson Moonwood is an original dark fairy-tale action adventure.","『猫猫黙示録 緋月の森』は、ダークなおとぎ話を描くオリジナルアクションアドベンチャーです。"],
  "「小燈，我會帶你活着返屋企。」":["「小灯，我会带你活着返屋企。」","\"Light, I will take you back to your house alive.\"","「ライト、私はあなたの家に戻ります生きます」"],
  "「小燈，我認得你。」":["「小灯，我认得你。」","\"A little lamp, I know you.\"","「ランプが少しずつ、気に入っています。」"],
