  "走進兩道綠色淨印，留在印內直至充滿。":["走进两道绿色净印，留在印内直至充满。","Enter each of the two green seals and stay inside until it is fully charged.","緑色の浄化の印は2つ。それぞれの中に入り、充填が完了するまでとどまろう。"],
