  "巡燈":["巡灯","Lantern Vigil","灯の巡回"],
  "巡燈、血月、無月分開計算。每個帳號、每個難度只顯示最佳一局：先比較已完成層數，同層比較完成該層嘅用時。總用時及歷次挑戰會留在個人紀錄。無敵模式同練習場不入榜。":["巡灯、血月、无月分开计算。每个帐号、每个难度只显示最佳一局：先比较已完成层数，同层比较完成该层的用时。总用时及历次挑战会留在个人纪录。无敌模式同练习场不入榜。","Each account number, each difficulty shows the best game: compare the number of layers that have been completed with the same level of time spent on it. The total time and challenges remain in the personal records. Invincible models do not go to the field.","各アカウント番号は、各難易度が最高のゲームを示しています。同じレベルの時間を費やしたレイヤー数を比較します。合計時間と課題は個人的な記録に残ります。 不可解なモデルはフィールドに行きません。"],
  "巡燈雷印":["巡灯雷印","Thunder Vigil","巡灯雷印"],
  "使用 Google 登入":["使用 Google 登录","Sign in with Google","Google でログイン"],
  "使用中":["使用中","Equipped","装備中"],
  "兩名頭目都已倒下。你可以多揀一份祝福，或者換走一份已有祝福，補齊另一個流派。":["两名头目都已倒下。你可以多选一份祝福，或者换走一份已有祝福，补齐另一个流派。","Both leaders have fallen. So choose another blessing, or replace it with one which has already been blessed, and complete the other.","両方のリーダーは落ちています。だから、別の祝福を選ぶか、すでに祝福されているものと交換し、もう一方を完成させます。"],
  "兩道大爪痕橫過車轍，旁邊貼住無月加派雙衛嘅命令。護送隊曾喺此等另一隻守衛會合。":["两道大爪痕横过车辙，旁边贴住无月加派双卫的命令。护送队曾在此等另一只守卫会合。","The escort team has been here waiting for another guard to meet.","護衛隊はここで会うために別のガードを待っています。"],
  "兩道血月斬交叉掠過，接住裂成四道外刃。":["两道血月斩交叉掠过，接住裂成四道外刃。","The two moons of blood were cut across and cut into four external blades.","血の2つの月は4つの外的な刃に渡され、切られました。"],
  "兩道巡邏爪痕":["两道巡逻爪痕","Two patrol claw marks.","2つのパトロール爪の印。"],
  "兩道命印輪流封路 · 第三斬由守夜者出手":["两道命印轮流封路 · 第三斩由守夜者出手","I'll seal the road in two ways.","2つの方法で道路をシールします。"],
  "兩種巨爪輪流護送名燈。無月封印下，原本一名守衛嘅出口會再加派一名。":["两种巨爪轮流护送名灯。无月封印下，原本一名守卫的出口会再加派一名。","The two claws rotate around escorting the lamps.","2つの爪はランプを護衛する周りを回転させます。"],
