  "卸下":["卸下","Unload","アンロード"],
  "受傷時自動披上短暫冰甲，震退並減速附近敵人。":["受伤时自动获得短暂冰甲，震退并减速附近敌人。","Taking damage briefly coats you in ice armor, knocking back and slowing nearby foes.","ダメージを受けると短時間だけ氷の鎧をまとい、周囲の敵を押し戻して減速させる。"],
  "受擊":["受击","Hit!","ヒット!"],
  "呢一輪時間碎咗。":["这一轮时间碎了。","This round of time is broken.","時間のこのラウンドは壊れています。"],
  "呢三份契印會一齊留喺封室。山下可以迎天光，記得你嘅人卻留唔住你個名。":["呢三份契印会一齐留在封室。山下可以迎天光，记得你的人却留不住你个名。","The three seals will stay in the sealed room. The mountains can meet the light, but your people cannot keep your name.","3つのシールは、密閉された部屋にとどまります。山は光を満たすことができますが、あなたの人々はあなたの名前を維持することはできません。"],
  "呢段挑戰到此為止。":["这段挑战到此为止。","That challenge has come to an end.","その挑戦は終わりに来ました。"],
  "呢頁說明遊戲點樣處理登入身份、訪客紀錄同排行榜資料。":["呢页说明游戏怎样处理登入身份、访客纪录同排行榜资料。","This page shows how the game handles entries, visitors' records and high rankings.","このページでは、ゲームがエントリ、訪問者の記録、高いランキングを処理する方法を紹介します。"],
  "呢個瀏覽器暫時未能保存挑戰紀錄。":["这个浏览器暂时未能保存挑战纪录。","This browser is temporarily unable to keep a challenge record.","このブラウザは、チャレンジレコードを保持できない状態です。"],
  "呢座林有百道封鎖。巡燈、血月、無月係同一夜嘅三種封印路徑，都通去王座；路線重疊，守衛同出口就會改位。":["呢座林有百道封锁。巡灯、血月、无月系同一夜的三种封印路径，都通去王座；路线重叠，守卫同出口就会改位。","In this forest, there are hundreds of blockades. The lights, the blood moon and the monthless sealing path, all of which go to the throne on the same night, overlap between them, and the guards change their positions with the exit.","この森では、何百もの遮断薬があります。光、血月と月の封印経路は、そのすべてが同じ夜にスローンに移動し、それらの間に重なり、ガードは出口で自分の位置を変更します。"],
