  "披上冰甲，寒潮會跟住你移動，最後裂開並冰封附近小怪。":["披上冰甲，寒潮会接著你移动，最后裂开并冰封附近小怪。","Put on the icecaps, and the tide will follow you, and it'll crack and freeze the little freaks around.","アイスキャップを置き、潮があなたをフォローし、周りの小さな群れをひび割れて凍結します。"],
  "披上短暫護甲，震擊附近敵人，受擊時觸發反震":["披上短暂护甲，震击附近敌人，受击时触发反震","Put on a short armor, shock the enemy in the vicinity, trigger a counter-shock when hit.","短い装甲の上に置き、周囲の敵をショックし、ヒットしたときにカウンターシャックをトリガーします。"],
  "抵達同通過嘅樓層會即時記下。敲響歸名鐘先計通關時間。":["抵达同通过的楼层会即时记下。敲响归名钟先计通关时间。","When you arrive on the same floor as you pass, write it down immediately.","同じフロアに着くと、すぐに書いてください。"],
