  "拖住移動，點一下普攻，快速短撥翻滾。點神器紋章會自動瞄準，拖住紋章可以手動瞄準，放手施技。點「調查」可同場景互動。":["拖住移动，点一下普攻，快速短拨翻滚。点神器纹章会自动瞄准，拖住纹章可以手动瞄准，放手施技。点「调查」可同场景互动。","Drag the movement, click on the generals, and roll fast and short. The dot marks will automatically aim, drag the dots can aim manually, and hand-to-hand. The dot \"investigates\" will interact with the scene.","動きをドラッグし、一般の方をクリックし、高速で短時間でロールします。ドットマークは自動的に目的を決め、点を手動でドラッグして、手元に移動できます。点「インヴェティゲート」はシーンと相互作用します。"],
  "拖動旋轉":["拖动旋转","Drag to rotate","ドラッグの回転"],
  "拖動移動 · 點按普攻 · 快撥翻滾":["拖动移动 · 点按普攻 · 快滑翻滚","Drag to move · Tap to attack · Flick to dodge","ドラッグで移動 · タップで攻撃 · フリックで回避"],
