  "放出多道直線攻擊":["放出多道直线攻击","Let's release multiple straight-line attacks.","複数の直線攻撃を解放しましょう。"],
  "放出近身衝擊，短暫加快移動同普攻":["放出近身冲击，短暂加快移动同普攻","Let's release a close impact, quick speed up movement and general attack.","衝撃を間近に解放し、動きおよび一般的な攻撃を加速して下さい。"],
