  "沿北面牆搜尋":["沿北面墙搜寻","Search the north wall.","北部の壁を探索する。"],
  "沿兩側裂窗重燃祭燈，驅散守門者的護影。":["沿两侧裂窗重燃祭灯，驱散守门者的护影。","Re-fired ceremonial lights along both sides of the window, dispersing the eyes of the gatekeeper.","窓の両側に沿って直火式ライトを点灯させ、ゲートキーパーの目を分散させます。"],
  "沿前方逐段爆開":["沿前方逐段爆开","Breaking through the front.","正面を抜ける。"],
  "沿面向逐段開啟地面封印":["沿面向逐段开启地面封印","Open the ground seal along a sector-by-section orientation.","部門別方向に沿って地上シールを開きます。"],
  "沿面向發出多道穿透光束":["沿面向发出多道穿透光束","A multi-channel penetrating beam along the direction.","方向に沿って複数のチャネル貫通ビーム。"],
  "沿着祭燈調查，線索會記在這裏。":["沿着祭灯调查，线索会记在这里。","Follow the lights, the clues will be here.","ライトを追って、ここで手がかりになります。"],
  "沿最後一下命中處敲出內外三層鐘聲；中心一擊最重。":["沿最后一下命中处敲出内外三层钟声；中心一击最重。","Three bells inside and outside are struck along the last hit; the centre is hit the hardest.","内側と外側の3つのベルは、最後のヒットに沿って打たれています。中心は最も困難なヒットしています。"],
  "沿裂縫兩端走，或翻滾越過裂地。":["沿裂缝两端走，或翻滚越过裂地。","Follow the cracks at both ends, or roll over the cracks.","両端の亀裂をフォローするか、亀裂の上にロールします。"],
  "沿瞄準方向連續落下四道雷擊，貫穿長列敵人。":["沿瞄准方向连续落下四道雷击，贯穿长列敌人。","Four successive thunderstorms were dropped in the direction of the aim, running through the enemy in the long row.","ゴールの方向に4つの連続雷雨が降下され、長い列で敵を駆け抜けました。"],
  "沿燈火尋找 ·":["沿灯火寻找 ·","Look for the light.","光を探します。"],
  "沿薄荷色箭嘴翻滾，避開兩邊攻擊。":["沿薄荷色箭嘴翻滚，避开两边攻击。","Scramble along mint coloured arrows, avoiding both sides of the attack.","攻撃の両側を避け、ミント色の矢印に沿ってスクランブルします。"],
  "波動加寬同延伸":["波动加宽同延伸","Fluctuation and extension","変動および延長"],
  "狐雷命中後會再跳電":["狐雷命中后会再跳电","Fox Thunder will jump again when it hits.","ヒットするとフォックスサンダーが再びジャンプします。"],
