  "直衝鎖定 · 離開紅線":["直冲锁定 · 离开红线","Straight ahead, lock it out of the red line.","直進すると、赤線からロックアウトします。"],
  "直擲接側掠，最後甩出大圓盤。去程和回程都能傷敵。":["直掷接侧掠，最后甩出大圆盘。去程和回程都能伤敌。","Throw the next side, and then throw out the big disk.","次の側面を投げ、それから大きいディスクを捨てて下さい。"],
  "空甲噬骨":["空甲噬骨","Empty armored bones.","空の装甲骨。"],
