  "空席上的名字":["空席上的名字","The name on the empty seat.","空席の名前。"],
  "空秤廳｜帳房階｜雙匙廊｜封銀池｜換糧櫃｜鎖櫃巷｜欠據庫｜金漆棧｜重鑰橋｜黿背金庫":["空秤厅｜帐房阶｜双匙廊｜封银池｜换粮柜｜锁柜巷｜欠据库｜金漆栈｜重钥桥｜鼋背金库","I'm in the middle of an empty clock room, and I've got two keys to cover my silver pool for food cabinets.","私は空の時計部屋の真ん中にあり、私は私の銀製のプールをフードキャビネットにカバーするために2つのキーを持っています。"],
