  "哥哥，阿婆今日問我係邊個。商會啲人話，欠據到期，要帶我去王座。你搵我嗰陣，就睇我畫嗰盞燈。":["哥哥，阿婆今日问我系边个。商会些人话，欠据到期，要带我去王座。你找我那时，就看我画那盏灯。","Brother, my grandmother asked me today: \"The Chamber of Commerce said that it was time to take me to the throne.\" When you came to me, I drew a lamp.","兄、祖母は今日私に尋ねました:「商会は、それが私を骨に連れて行く時間だったと言いました。」あなたが私に来たとき、私はランプを引いた。"],
  "哥哥，阿婆叫得出我個名喇。佢留咗兩碗粥，話等我哋一齊食。":["哥哥，奶奶能叫出我的名字了。她留了两碗粥，说等我们一起吃。","Big brother, Grandma remembers my name! She saved two bowls of congee for us to eat together.","お兄ちゃん、おばあちゃんが私の名前を呼んだよ！ お粥を二杯取っておいて、一緒に食べようって。"],
