  "逆羽標記令敵人易傷":["逆羽标记令敌人易伤","Anti-feed marks make the enemy vulnerable.","敵に脆弱なマークがつく。"],
  "逆流將周圍敵人扯返入風眼":["逆流将周围敌人拖回入风眼","The reverse current drags the enemy back into the wind.","逆電流は敵を風にドラッグします。"],
  "逆風回函戟":["逆风回函戟","Headwind Dispatch Halberd","逆風の返函戟"],
