  "鬼魂彈令目標易傷更耐":["鬼魂弹令目标易伤更耐","Ghost bombs make the target more vulnerable.","ゴースト爆弾は、ターゲットをより脆弱にする."],
  "鬼魂彈加強易傷標記":["鬼魂弹加强易伤标记","Ghost bombs reinforce the vulnerable markings.","ゴースト爆弾は脆弱なマーキングを強化します。"],
