  "匙柄寫住「收成已足，請開倉」。商會卻把副匙封入金庫，將存糧留待高價轉售。":["匙柄写住「收成已足，请开仓」。商会却把副匙封入金库，将存粮留待高价转售。","The key handle says, \"The harvest is enough. Please open the warehouse.\" The Chamber of Commerce seals the spoon into the vault and keeps it for sale at a high price.","重要なハンドルは「収穫は十分です。倉庫を開けて下さい」と言います。商会は金庫にスプーンを密封し、高い価格で販売するために保ちます。"],
  "啄焰":["啄焰","Flames.","炎。"],
  "商會把異地武者同妖物嘅契印接入王冠。有啲自願守庫，有啲連自己受控制都唔知。入口借出嘅神器亦帶住舊印，會引來追討。":["商会把异地武者同妖物的契印接入王冠。有些自愿守库，有些连自己受控制都不知。入口借出的神器亦带住旧印，会引来追讨。","The Chamber of Commerce enters into the crown the seal of a foreigner with demons. Some voluntarily hold their own banks, some of which are not even aware of their control.","商会は、悪魔と外国人のシールを冠に入っています。 一部の自主的に自分の銀行を保持し、そのうちのいくつかは、その制御を認識していません。"],
  "商會的印模":["商会的印模","The Chamber of Commerce Seal.","商業シールのチャンバー。"],
  "商會金庫":["商会金库","Chamber of Commerce Treasury","商会 Treasury"],
  "問更深嘅路點解有更多金幣":["问更深的路为什么有更多金币","Asking why there are more gold coins on the deeper road.","より深い道に金貨がもっとある理由を尋ねる。"],
  "問點解守衛同神器都聽商會命令":["问为什么守卫同神器都听商会命令","Ask why the guards follow the orders of the Chamber of Commerce.","ガードが商会の注文に従う理由を尋ねてください。"],
