  "寄影空弦弓":["寄影空弦弓","Hollowstring Bow","寄影の空弦弓"],
  "寄影空弦弓・餘響":["寄影空弦弓・余响","Sending an empty string bow.","空の文字列弓を送信します。"],
  "將小燈嗰頁帶出去。每年同我講一次，佢過得點就得。":["将小灯那页带出去。每年同我讲一次，他过得点就得。","Take the little light pages out. Tell me once a year, he'll be fine.","小さな光のページを外します。 1年1回私に教えてください、彼は良いでしょう。"],
  "將兩隻碗並排放好":["将两只碗并排放好","Two bowls and two bowls.","2本のボウルと2つのボウル。"],
  "將第三擊碰到嘅敵人拉返嚟，再斬向受傷目標。":["将第三击碰到的敌人拉回来，再斩向受伤目标。","Pull back the enemy that hit him in the third strike and then cut the target.","3番目のストライクで彼をヒットし、ターゲットをカットする敵を後ろに引きます。"],
  "將會換走":["将会换走","It's going to be replaced.","交換するつもりです。"],
  "將榴彈直接落喺重炮命中處，兩次爆開。":["将榴弹直接落在重炮命中处，两次爆开。","The grenade was dropped directly at the point of the heavy artillery fire and exploded twice.","重兵器火の点で直接落とされ、二度爆発した。"],
  "將槍收好。等村民睇到，今次有乜嘢可以靠得住。":["将枪收好。等村民看到，今次有什么可以靠得住。","Put your guns away. When the villagers see what they can rely on this time.","銃を捨ててください。村の人がこの時間に頼ることができるものを見るとき。"],
