  "減少神器冷卻，強化自動雷擊。":["减少神器冷却，强化自动雷击。","Reduces Relic cooldown and strengthens automatic lightning strikes.","神器の再使用時間を短縮し、自動で落ちる雷を強化する。"],
  "減少閃光與震動":["减少闪光与震动","Reduce flash and vibration","フラッシュと振動を削減"],
  "焚血雷印":["焚血雷印","Blood-thirsty.","血の渇き。"],
  "焚信空弦弓":["焚信空弦弓","Letterburn Bow","焚書の空弦弓"],
  "焚信空弦弓・餘響":["焚信空弦弓・余响","Burning an empty string bow.","空の文字列弓を焼く。"],
