  "焚契燈剪":["焚契灯剪","Oathburn Lantern Shears","焚約の灯鋏"],
  "焚契燈剪・餘響":["焚契灯剪・余响","♪ Burn the lights cut ♪","♪ライトカットを焼く♪"],
  "焚契護衣":["焚契护衣","Burning Pact Mantle","焚約の護衣"],
  "無人簽名的證詞":["无人签名的证词","Unsigned testimony","無署名の証言"],
  "無月":["无月","Moonless","無月"],
  "無月 · 第 75 關":["无月 · 第 75 关","Month 75","月 75"],
  "無月引魂燈":["无月引魂灯","Moonless Soul Lantern","無月の導魂灯"],
  "無月歸名者":["无月归名者","Moonless Namekeeper","無月の名還し"],
  "無月引魂燈與無月歸名者":["无月引魂灯与无月归名者","Moonless Soul Lantern and Moonless Namekeeper","無月の導魂灯と無月の名還し"],
  "無月雙頭目係加派嘅守衛；車轍繼續指向囚名庫。":["无月双头目系加派的守卫；车辙继续指向囚名库。","The bi-heads of the month were additional guards; the tracks continued to point to the prison hangar.","月のバイヘッドは追加のガードでした。トラックは刑務所のハンガーに点在し続けました。"],
  "無名庭":["无名庭","Nameless Court","無名の庭"],
  "無名庭・八針織者":["无名庭・八针织者","Nameless Court · Eight-Needle Weaver","無名の庭・八針の織り手"],
  "無名庭・空面聽差":["无名庭・空面听差","Nameless Court · Faceless Errand Runner","無名の庭・空顔の使い"],
