  "無名庭・銅鐘司夜":["无名庭・铜钟司夜","Nameless Court · Copper Bell Watchman","無名の庭・銅鐘の夜番"],
  "無名庭・鎖函監":["无名庭・锁函监","Nameless Court · Casket Jailer","無名の庭・鎖函の獄監"],
  "無面討債人":["无面讨债人","No-face debt collector.","表面負債のコレクター無し。"],
  "無頁吞聲匣":["无页吞声匣","Pageless Hushbox","頁なき呑声匣"],
  "無頁吞聲匣・餘響":["无页吞声匣・余响","No Page Swallow Cassette.","いいえページスワローカセット。"],
  "無頁書脊杖":["无页书脊杖","Pageless Spine Staff","頁なき書背杖"],
  "無頁書脊杖・餘響":["无页书脊杖・余响","No pagebook scepter.","ページブックスセプターはありません。"],
  "無敵":["无敌","Invincible","無敵"],
  "無敵測試模式 ·":["无敌测试模式 ·","Invincible test mode.","可燃性テストモード。"],
