  "登入":["登录","Sign in","ログイン"],
  "登入未能完成，訪客紀錄仍然保留。請稍後重新登入。":["登入未能完成，访客纪录仍然保留。请稍后重新登入。","You can re-entry later.","後で再入力できます。"],
  "登入同全服排行榜暫未開放。訪客紀錄會繼續保存，之後可以合併到帳號。":["登入同全服排行榜暂未开放。访客纪录会继续保存，之后可以合并到帐号。","The entry to the full-service list is not open.","フルサービスの一覧へのエントリーは開いていません。"],
  "登入完成。":["登入完成。","Login complete.","ログイン完了です。"],
  "登入身份":["登入身份","Login Identity","ログイン アイデンティティ"],
  "登入尚未開放。成績已保存在此裝置，之後可以合併並上榜。":["登入尚未开放。成绩已保存在此装置，之后可以合并并登入排行榜。","Login is not yet open. Achievements are stored in this device, which can then be merged and placed on the list.","ログインはまだ開いていません。 結果は、このデバイスに保存され、リストにマージして配置することができます。"],
  "登入後合併此裝置嘅訪客紀錄。":["登入后合并此装置的访客纪录。","Enter and merge the visitor records for this device.","訪問者の記録をこのデバイスに入力し、マージします。"],
  "登入與遊戲進度":["登入与游戏进度","Login and Game Progress","ログインとゲームの進捗"],
  "登出此裝置":["登出此装置","Logout this device","このデバイスをログアウトする"],
  "發出逐段擴散嘅元素波":["发出逐段扩散的元素波","Sending Element Waves of Dispersion","分散の要素波の送信"],
  "睇 1 個廣告復活":["看 1 个广告复活","Look, one ad is coming back.","見れば、1つの広告が戻ってきます。"],
  "睇完 1 個廣告可原地復活，回復一半生命。本局只可用一次，遠征排行以倒地前嘅成績為準。":["看完 1 个广告可原地复活，回复一半生命。本局只可用一次，远征排行以倒地前的成绩为准。","After reading one ad, you can revive yourself and return to half your life.","1つの広告を読んだ後、あなたは自分自身を復活させ、あなたの人生の半分に戻ることができます。"],
  "睇準薄荷色箭嘴，向箭嘴方向翻滾。":["看准薄荷色箭嘴，向箭嘴方向翻滚。","Watch the mint-coloured arrows and roll in the direction of them.","ミント色の矢印を見て、それら方向にロールします。"],
  "睇頭目":["看头目","Look at the boss.","ボスを見てください。"],
  "短刺接兩下快刺，最後踏前重突貫穿敵人。":["短刺接两下快刺，最后踏前重突贯穿敌人。","The short-stroke stings two times, and the final step leads back to the enemy.","ショートストロークは2回、最終ステップは敵に戻ります。"],
  "短暫提高移速及攻擊速度":["短暂提高移速及攻击速度","Short-term increase in speed and speed of attack.","攻撃の速度と速度の短期増加。"],
  "稍作休息":["稍作休息","Paused","一時休憩"],
  "稍後重寄":["稍后重发","Resend later","後でもう一度送信"],
  "等我搵到完全收起契印嘅方法，我先會放低呢盞燈。":["等我找到完全收起契印的方法，我先会放低这盏灯。","I'll lower the lamp when I find a way to put it away completely.","ランプを下げて、完全に置く方法を見つけます。"],
  "等候命中":["等候命中","Wait for the hit.","ヒットを待ってください。"],
  "等蝕日者走近銅鏡，再引牠用墜擊轟向鏡面。":["等蚀日者走近铜镜，再引牠用坠击轰向镜面。","And when the sun-earner approaches the copper lens, he will lead him to the mirror with a crash.","そして、太陽が銅のレンズに近づくと、彼は衝突で鏡に彼を導きます。"],
  "結束本次挑戰":["结束本次挑战","End this challenge.","このチャレンジを終わらせます。"],
  "結束本局":["结束本局","End of the game.","ゲーム終了。"],
  "結界再起":["结界再起","We're back in line.","折り返し点を追って、"],
  "菌根童":["菌根童","Bacteria.","細菌。"],
  "菌絲保存小燈被運送途中嘅童謠，木牌同運送編號證實路線通向囚名庫。此處聽到嘅仍係回音。":["菌丝保存小灯被运送途中的童谣，木牌同运送编号证实路线通向囚名库。此处听到的仍系回音。","This section still hears echoes the rumour that mycel kept the light while it was being transported, and the number of the shipment confirms that the route leads to the prison name.","このセクションでは、mycel が輸送中に光を保ち、出荷の数はルートが刑務所の名前につながることを確認します。"],
  "菌絲重播原有嘅旋律。你按亮起嘅車轍，找出下一段路。":["菌丝重播原有的旋律。你按亮起的车辙，找出下一段路。","Mystic replays the original melody. You press the light of the car and find the next path.","ミスティックは、元のメロディーを再生します。あなたは車の光を押し、次のパスを見つけます。"],
  "蛛絲纏翅":["蛛丝缠翅","The spider's got wings.","スイダーの羽根がついた。"],
  "裁紙箭陣":["裁纸箭阵","Paper cut-off arrows","ペーパーカットオフ矢印"],
  "裁燈使":["裁灯使","Lantern Reaper","灯裁ちの使徒"],
