  "裂石妖":["裂石妖","The fissure.","ファイザー。"],
  "裂冰十字":["裂冰十字","Cracking Ice Cross","氷の十字架を割る"],
  "裂地封路 · 改道或翻滾":["裂地封路 · 改道或翻滚","- Breaking the road. - Change or roll.","- 道路を破る。 - 変更またはロール。"],
  "裂地熄燈":["裂地熄灯","Crack out the lights.","ライトをクラックアウトします。"],
  "裂帆夜航翎":["裂帆夜航翎","Riven Sail Plume","裂帆の夜航羽"],
  "裂帆夜航翎・餘響":["裂帆夜航翎・余响","♪ Breaking sails and night sails ♪","♪ 船と夜の帆を破る♪"],
  "裂風折刃":["裂风折刃","Galebreaker","裂風の折刃"],
  "裂紗纏行":["裂纱缠行","Riven-Veil Crawler","裂紗の這い手"],
  "裂開的印模":["裂开的印模","Fragmented marks.","フラグメントマーク。"],
  "裂腹蠟童":["裂腹蜡童","Cracker wax boy.","ク ラッカーワックス少年。"],
  "裂隙導電尺":["裂隙导电尺","Rift Conductor","裂隙の導雷剣"],
  "裂隙導電尺・餘響":["裂隙导电尺・余响","Cracking conductor ruler.","コンダクターの定規を割れること。"],
  "裂輪命中後召回圓盤，斬過沿途敵人，再收成一圈電環。":["裂轮命中后召回圆盘，斩过沿途敌人，再收成一圈电环。","After the breaker's life, he called back the disc, cut off the enemy along the way and harvested another round of electrons.","ブレーカの命の後、彼はディスクを取り戻し、途中で敵をカットし、電子の別のラウンドを収穫しました。"],
  "裂縫已打開 · 向側邊走，引頭目離開裂縫":["裂缝已打开 · 向侧边走，引头目离开裂缝","The cracks have been opened.....to the side, lead the head away from the cracks.","亀裂が開いてきました... ..to側には、頭を亀裂から離します。"],
  "裂霜蒸焰":["裂霜蒸焰","Fragmentation.","フラグメンテーション。"],
  "裂鎧雷":["裂铠雷","Cracker Thunder","亀甲サンダー"],
  "裂爐暴骨":["裂炉暴骨","Bones of the fibre.","繊維の骨。"],
  "貼着蛛絲引送靈者移影，讓牠落在蛛絲上。":["贴着蛛丝引送灵者移影，让牠落在蛛丝上。","With a thread to lead the spiriters away, so that it falls on the spider.","スピラーを離れて導く糸を使って、スイダーに落ちます。"],
