  "階：":["阶：","STEPS:","ステップ:"],
  "雲雷會從落點跳去附近敵人":["云雷会从落点跳去附近敌人","Thunder will jump from a drop point to a nearby enemy.","ドロップポイントから近くの敵へジャンプします。"],
  "雲端紀錄包括每局挑戰識別碼、難度、已完成層數、完成該層用時、總用時、擊倒數、神器、技能分支、挑戰狀態、開始時間及離線提交標記。呢啲資料用於保存歷次挑戰、合併成績同計算各難度最佳排行。":["云端纪录包括每局挑战识别码、难度、已完成层数、完成该层用时、总用时、击倒数、神器、技能分支、挑战状态、开始时间及离线提交标记。呢些资料用于保存历次挑战、合并成绩同计算各难度最佳排行。","The cloud records include the challenge identification code for each round, difficulty, number of layers completed, time spent to complete the layer, total time, countdowns, theorems, skill branches, challenge states, start times and offline submission markers. This information is used to save successive challenges, line up the combined scores and calculate the best difficulties.","クラウドレコードには、各ラウンド、難易度、レイヤーの完成度数、合計時間、カウントダウン、理論、スキルブランチ、チャレンジの状態、開始時間、オフライン投稿マーカーのチャレンジ識別コードが含まれます。 この情報は、成功課題を保存し、組み合わせたスコアを並べて、最高の困難を計算するために使用されます。"],
  "雲端紀錄會保留供個人歷史及排行榜使用。如需查詢或要求刪除帳號與雲端紀錄，請透過":["云端纪录会保留供个人历史及排行榜使用。如需查询或要求删除帐号与云端纪录，请透过","Cloud records are kept for personal history and ranking.","クラウドレコードは、個人履歴やランキングのために保存されます。"],
  "雲端帳號目前保存登入身份及挑戰紀錄。金幣、訓練所強化、外觀解鎖同其他本機遊戲設定，仍保存在原本瀏覽器。更新、切換裝置或清除本機資料時，請留意呢個分別。":["云端帐号目前保存登入身份及挑战纪录。金币、训练所强化、外观解锁同其他本机游戏设定，仍保存在原本浏览器。更新、切换装置或清除本机资料时，请留意这个分别。","A cloud account is currently maintained to record the login and challenge. Gold coins, Training Hall enhanced, appearance unlocks and other local games are set up and kept in the original browser.","クラウドアカウントは現在、ログインとチャレンジを記録するために維持されます。ゴールドコイン、訓練所の強化、外観のロック解除、その他のローカルゲームは、元のブラウザで設定および保存されます。"],
