  "嗰件《0》仲留住我嘅名字，交返畀我！":["那件《0》还留着我的名字，把它还给我！","My name is still inside 《0》. Give it back!","《0》にはまだ私の名が宿っている。返せ！"],
  "嗰件三葉測風杖仲留住我嘅名字，交返畀我！":["那件三叶测风杖还留住我的名字，交返给我！","That three-leaf cane still has my name. Give it back to me!","その3リーフの杖はまだ私の名前を持っています。 私にそれを返してください!"],
  "嗰件引雷沙漏仲留住我嘅名字，交返畀我！":["那件引雷沙漏还留住我的名字，交返给我！","I still have my name. Give it back to me!","私はまだ私の名前を持っています。 私に戻ってください!"],
  "嗰件未眠紙偶仲留住我嘅名字，交返畀我！":["那件未眠纸偶还留住我的名字，交返给我！","The unsleaved paper still has my name. Give it back to me!","未熟な紙は、まだ私の名前を持っています。私にそれを返さ!"],
  "嗰件未寄出的燈匣仲留住我嘅名字，交返畀我！":["那件未寄出的灯匣还留住我的名字，交返给我！","The unsendable lightbox still has my name. Give it back to me!","望ましくないライトボックスは、まだ私の名前を持っています。私にそれを与えます!"],
  "嗰件末燈提芯仲留住我嘅名字，交返畀我！":["那件末灯提芯还留住我的名字，交返给我！","That last lantern still has my name. Give it back to me!","その最後のランタンはまだ私の名前を持っています。 私に戻ってそれを与えます!"],
  "嗰件永夜校時杖仲留住我嘅名字，交返畀我！":["那件永夜校时杖还留住我的名字，交返给我！","The staff of the Eternal Night School still has my name. Give it back to me!","Eternal Night Schoolのスタッフは、まだ私の名前を持っています。 私に戻ってください!"],
  "嗰件白封印槌仲留住我嘅名字，交返畀我！":["那件白封印槌还留住我的名字，交返给我！","The white seal still keeps my name. Give it back to me!","白いシールは、名前を保ちます。 私に戻ってください!"],
  "嗰件冰函直尺仲留住我嘅名字，交返畀我！":["那件冰函直尺还留住我的名字，交返给我！","I'm still keeping my name on the ice. Give it back to me!","私はまだ氷に私の名前を守っています。 私にそれを返してください!"],
  "嗰件回願吞墨鉗仲留住我嘅名字，交返畀我！":["那件回愿吞墨钳还留住我的名字，交返给我！","I still have my name on the inkstick. Give it back to me!","私はまだインクスティックに私の名前を持っています。 私にそれを与えます!"],
  "嗰件沉鐘印槌仲留住我嘅名字，交返畀我！":["那件沉钟印槌还留住我的名字，交返给我！","I still have my name on that ding-tao. Give it back to me!","私はまだ私の名前を持っています その ding-tao. 私にそれを返す!"],
