  "嗰件夜航鉤月刀仲留住我嘅名字，交返畀我！":["那件夜航钩月刀还留住我的名字，交返给我！","The night hook knife still keeps my name. Give it back to me!","夜のホックナイフはまだ私の名前を保ちます。私にそれを与えます!"],
