  "嗰件拘雷玻璃匣仲留住我嘅名字，交返畀我！":["那件拘雷玻璃匣还留住我的名字，交返给我！","I still have my name on that Tray. Give it back to me!","私はまだそのトレイに私の名前を持っています。 私に戻ってそれを与えます!"],
