  "碑上寫住：佢仲活着，我只係想唔起佢個名。旁邊另有一列真正嘅墳，刻字同樣空白。":["碑上写住：他还活着，我只系想不起他个名。旁边另有一列真正的坟，刻字同样空白。","It is written: \"He is alive, and I can't remember his name. And there is a true grave next to it, with the same gravitation.\"","「彼は生きて、自分の名前を覚えない」と書かれています。それに隣接する真の墓があります。"],
  "碗底刻住「等佢活着出庫」。隔壁墓列則擺住往生者生前用過嘅器皿，分別等候相認同送別。":["碗底刻住「等他活着出库」。隔壁墓列则摆住往生者生前用过的器皿，分别等候相认同送别。","The bottom of the bowl is carved \"when he gets out of the store alive.\"","ボウルの一番下が刻まれた「彼が店から離れるとき」。"],
  "碗底寫住「等佢活着出庫」。你將有缺口嗰隻放返近門一邊，畀等候嘅人睇見。":["碗底写住「等他活着出库」。你将有缺口那只放返近门一边，给等候的人看见。","The bottom of the bowl says, \"Wait until he comes out of the vault alive.\" You will have a gap that will be placed only by the side of the door, for those who wait.","ボウルの一番下は、「彼が生きたボルトから出てくるまで待ちます」と言います。あなたは、待つ人のために、ドアの側にのみ配置されるギャップを持っています。"],
