  "摺成花的名紙":["折成花的名纸","Famous paper.","有名なペーパー。"],
  "敲響":["敲响","Resonant Strike","ノック。"],
  "敲響歸名鐘":["敲响归名钟","Ringing the name bell.","名前ベルを鳴らす。"],
  "槍刺":["枪刺","Spear Thrust","ガンショット。"],
  "滲墨毒幕":["渗墨毒幕","Seeping Venom Screen","滲墨の毒幕"],
  "滿月裂輪":["满月裂轮","A full moon.","満月。"],
  "滿弦奔雷":["满弦奔雷","It's full of string.","文字列がいっぱいです。"],
  "滿弦接技會射出三道分岔雷箭，箭路盡頭落下星雷。":["满弦接技会射出三道分岔雷箭，箭路尽头落下星雷。","The stringwork will shoot three forklifts and drop a star at the end of the arrow road.","3つのフォークリフトを撮影し、矢印ロードの最後に星をドロップします。"],
  "滿弦雷矢":["满弦雷矢","♪ All the string ♪","♪すべての文字列♪"],
  "滿弦箭射中後，技能從中箭目標起跳，連鎖至附近敵人。":["满弦箭射中后，技能从中箭目标起跳，连锁至附近敌人。","When a string of arrows is fired, the skills jump from the center arrow to the nearby enemy.","矢印の文字列が発射されると、中心矢印から近くの敵にジャンプする。"],
  "熄燈墨瓶杖":["熄灯墨瓶杖","Lampsnuff Ink Staff","消灯の墨瓶杖"],
  "熄燈墨瓶杖・餘響":["熄灯墨瓶杖・余响","Lights out the ink stick.","インク棒をつけて下さい。"],
  "熄燈爆裂":["熄灯爆裂","Lights out and burst.","ライトアウトとバースト。"],
  "熔井反湧":["熔井反涌","Smelting wells retreating.","製錬の井戸の退去。"],
  "熔井崩甲":["熔井崩甲","Melting well collapses.","よく崩壊を溶かす。"],
  "熔火切開橫路，南北兩道缺口錯開。":["熔火切开横路，南北两道缺口错开。","The melting fire cuts across the road and the gap between North and South is staggered.","道路を越え、北と南の隙間を切る溶融火は驚異的です。"],
  "熔金長齒":["熔金长齿","Melting gold long teeth.","金の長い歯を溶かす。"],
  "熔星爐":["熔星炉","Melting fire.","溶ける火。"],
  "熔骨火魔":["熔骨火魔","Melting Fire.","溶ける火。"],
  "熔鐵三擊":["熔铁三击","Melting iron three.","溶ける鉄3。"],
  "獄門三鳴":["狱门三鸣","The prison door is three clicks.","刑務所のドアは3つのかちりと言う音です。"],
  "獄爐豬王":["狱炉猪王","King of Pigs in the Warplace.","戦場の豚の王。"],
  "磁場吸入外圍敵人":["磁场吸入外围敌人","The magnetic field inhales the outer enemy.","磁場は外敵を吸入する。"],
