  "維護頁":["维护页","Maintenance Page","メンテナンスページ"],
  "網站由 GitHub Pages 提供。Google、Supabase、Resend 及網站寄存服務會按各自服務政策處理提供服務所需嘅連線及操作紀錄。遊戲目前嘅登入、同步同公開內容以本頁及實際介面說明為準。":["网站由 GitHub Pages 提供。Google、Supabase、Resend 及网站寄存服务会按各自服务政策处理提供服务所需的连线及操作纪录。游戏目前的登入、同步同公开内容以本页及实际介面说明为准。","The website is provided by GitHub Pages. Google, Supabasse, Resend, and the website's hosting services handle the connection and operating records required for service delivery in accordance with their respective service policies.","このウェブサイトはGitHub Pages. Google、Supabasse、Resend、およびウェブサイトのホスティングサービスは、それぞれのサービスポリシーに従ってサービスの配信に必要な接続と運用記録を処理します。"],
