  "腐墨蘆管杖・餘響":["腐墨芦管杖・余响","The ink wand. It's still ringing.","インクの杖。それはまだリングです。"],
  "與":["与","and","そして、"],
  "蒼龍雷獄":["苍龙雷狱","Dragon Lai Prison.","ドラゴンライ・プリソン。"],
  "蓄力已打斷 · 斷冠仍會出斬，快避開紅線。":["蓄力已打断 · 断冠仍会出斩，快避开红线。","The energy has been broken and the crown is still cut, get out of the red line.","エネルギーは壊れ、王冠はまだ切断され、赤いラインから出ます。"],
  "蓄招完再留一個追身咒印。":["蓄招完再留一个追身咒印。","Leave another cursing mark after the tip.","先端の後に別の硬化マークを残します。"],
  "蓄招時護甲更厚；重擊可破盾。":["蓄招时护甲更厚；重击可破盾。","Armor protection is thicker when recruitment is made; the shield can be broken if hit hard.","採用がなされたとき、防護剤はより厚いです。硬い場合はシールドを破ることができます。"],
  "蓄滿月印後，貼印引蛾冠移影落下。":["蓄满月印后，贴印引蛾冠移影落下。","After full moonmarking, the sticker rolls down.","月面を満たせば、ステッカーは転がります。"],
  "蓄滿命印":["蓄满命印","It's full of life.","人生がいっぱいです。"],
  "蓄滿命印後，引守夜者踏進自己劈出的封路裂縫。":["蓄满命印后，引守夜者踏进自己劈出的封路裂缝。","When the seal of life is full, he who guides the Night's Watch enters the cracks of his own sealed road.","人生の印がいっぱいになると、夜の時計をガイドする彼は自分の密封された道の亀裂に入ります。"],
  "蓄滿綠色淨印後，引蜿龍踏進印內。":["蓄满绿色净印后，引蜿龙踏进印内。","When the green net print is filled, the lead dragon sets in.","緑色のネットプリントが充填されると、リードドラゴンがセットされます。"],
