  "領取頭目遺物":["领取头目遗物","Get the head's belongings.","ヘッドの持ち物を取得します。"],
  "領糧數目清清楚楚，姓名一欄俾咒印遮住。守燈一照，簿底浮出「以真名抵糧」同四枚商印。原來領糧收據被偷改成契約。":["领粮数目清清楚楚，姓名栏却被咒印遮住。守灯一照，簿底浮出「以真名抵粮」和四枚商印。原来领粮收据被偷改成了契约。","The ration amounts are plain to see, but a sigil hides the names. Your lantern reveals the words “Grain in exchange for a true name” beneath four merchant seals. Someone turned the receipts into a pact.","配給量は明記されているが、名前の欄は呪印で隠されている。灯を当てると帳簿の奥に「真名を穀物の代価とする」の文字と四つの商印が浮かぶ。配給の受領書は契約にすり替えられていた。"],
  "鳳鳴命中後，三道火浪在命中處交會，令敵人易傷。":["凤鸣命中后，三道火浪在命中处交会，令敌人易伤。","When Feng was hit, three waves of fire met at the point of impact, leaving the enemy vulnerable.","Fengがヒットすると、火の3つの波が衝撃の点で遭遇し、敵を脆弱に残します。"],
