  "墜彩玻璃廊｜缺翼樓梯｜塵星步道｜鎖詠亭｜熄燭祭室｜翅粉穹門｜星縫｜黑玻璃台｜蛾燈階｜無月聖所":["坠彩玻璃廊｜缺翼楼梯｜尘星步道｜锁咏亭｜熄烛祭室｜翅粉穹门｜星缝｜黑玻璃台｜蛾灯阶｜无月圣所","The black-glass glitter is a moonless lantern on the pedestal.","黒いガラスのきらめきは、ペデスタルに月の無灯籠です。"],
  "增加":["增加","Increase","増加する"],
  "增加普通攻擊距離與第三擊傷害。":["增加普通攻击距离与第三击伤害。","Increases basic attack reach and the third hit's damage.","通常攻撃の間合いが伸び、3撃目のダメージが増加する。"],
