  "靠近角將引落冰，紅圈鎖定後離開牠身旁。":["靠近角将引落冰，红圈锁定后离开牠身旁。","Near the corner will lead to ice and the red circle will be locked and left by its side.","コーナー付近は氷につながり、赤の丸がロックされ、その側で左になります。"],
