  "機械人日後守住橋頭送糧。連以前替商會收糧嘅橋卒，都要按村會公布嘅名冊領取口糧。":["机械人日后守住桥头送粮。连以前替商会收粮的桥卒，都要按村会公布的名册领取口粮。","The mechanics will then hold the bridge head and feed.","メカニックスは、橋頭と餌を握ります。"],
  "機械人沿雷達掃描線逐段架起扶手。最後一台用機身頂住下沉嘅石板，等所有人行過先收索。":["机械人沿雷达扫描线逐段架起扶手。最后一台用机身顶住下沉的石板，等所有人行过先收索。","The robot sets up the arming section along the radar scan line. The last one holds the sinking tablet with the fuselage and waits for everyone to get past it.","ロボットは、レーダースキャンラインに沿って武装セクションを設定します。最後の1つは、胴体と沈没タブレットを保持し、誰もがそれを過去に取得するのを待っています。"],
