  "燈火重燃":["灯火重燃","Lights are on fire again.","再び光が火にかかっています。"],
  "燈火熄滅。避開黏足的蛛絲，貼墓柱走。":["灯火熄灭。避开黏足的蛛丝，贴墓柱走。","The lights go out. Get away from the sticky spiders and put up a gravepost.","光が出てきます。 粘りのあるスイダーから逃げ、墓地を上る。"],
