  "頭一年，大家自願守夜；第二年，缺席已被視為背叛。小燈帶走自己盞燈。四商會嘅主契斷咗，你卻建立起另一套索取。":["头一年，大家自愿守夜；第二年，缺席已被视为背叛。小灯带走自己盏灯。四商会的主契断了，你却建立起另一套索取。","For the first year, everyone voluntarily stayed at night; for the second year, absence was considered a betrayal. The light took away their own lamp. And when the Four Merchant Guilds broke their contract, you set up another claim.","最初の1年間、誰もが夜に過度に滞在しました。 2年目では、不在は裏切りと見なされていました。 光は自分のランプを取り去りました。 そして、4つの商会が契約を破ったとき、あなたは別の主張を設定しました。"],
