  "織風亭・紙翼巡獵":["织风亭・纸翼巡猎","Windweaver Pavilion · Paperwing Stalker","織風の亭・紙翼の狩人"],
  "織風亭・旋軌守望":["织风亭・旋轨守望","Windweaver Pavilion · Orbit Sentinel","織風の亭・旋軌の番人"],
  "織風亭・裁燈使":["织风亭・裁灯使","Windweaver Pavilion · Lantern Reaper","織風の亭・灯裁ちの使徒"],
  "織風亭・裂紗纏行":["织风亭・裂纱缠行","Windweaver Pavilion · Riven-Veil Crawler","織風の亭・裂紗の這い手"],
  "織風亭・銅鐘司夜":["织风亭・铜钟司夜","Windweaver Pavilion · Copper Bell Watchman","織風の亭・銅鐘の夜番"],
  "織風亭・墨蹄獵犬":["织风亭・墨蹄猎犬","Windweaver Pavilion · Inkhoof Hound","織風の亭・墨蹄の猟犬"],
  "織風亭・燃芯樹偶":["织风亭・燃芯树偶","Windweaver Pavilion · Burning Wick Effigy","織風の亭・燃芯の木偶"],
